const rows = $input.all().map(i => i.json);
return [{
  json: {
    list: rows.map(r => `${r.keyword} | vol ${r.volume} | ${r.intent}`).join('\n')
  }
}];

const existing = new Set(
  $('GetExistingKeywords').all()
    .map(i => (i.json.keyword || '').toLowerCase().trim())
    .filter(Boolean)
);

return $('ScoreKeywords').all()
  .filter(i => !existing.has(i.json.keyword.toLowerCase().trim()))
  .map(i => ({ json: i.json }));

const items = $input.first().json.tasks?.[0]?.result?.[0]?.items ?? [];

return items.map(i => ({
  json: {
    keyword: i.keyword_data.keyword,
    volume: i.keyword_data.keyword_info?.search_volume ?? 0,
    difficulty: i.keyword_data.keyword_properties?.keyword_difficulty ?? null,
    intent: i.keyword_data.search_intent_info?.main_intent ?? null,
    cpc: i.keyword_data.keyword_info?.cpc ?? null,
    has_paa: i.keyword_data.serp_info?.serp_item_types?.includes('people_also_ask') ?? false,
    related_keywords: i.related_keywords ?? []
  }
}));

const raw = $input.first().json.output[0].content[0].text
  .replace(/```json|```/g, '')
  .trim();
const keep = JSON.parse(raw).keep.map(k => k.toLowerCase().trim());

const rows = $('FilterKeywords').all().map(i => i.json);

return rows
  .filter(r => keep.includes(r.keyword.toLowerCase().trim()))
  .map(r => ({
    json: {
      ...r,
      score: r.volume / Math.pow(r.difficulty + 1, 2)
    }
  }));

const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'];

const rows = $input.all().map(i => i.json)
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

return rows.map((r, i) => ({
  json: {
    ...r,
    scheduled_day: days[i],
    status: r.source === 'related_backfill' ? 'pending_draft_needs_data' : 'pending_draft'
  }
}));

const current = $input.all().map(i => i.json);
const needed = 5 - current.length;

if (needed <= 0) return current.map(r => ({ json: r }));

const existing = new Set(
  $('GetExistingKeywords').all()
    .map(i => (i.json.keyword || '').toLowerCase().trim())
);
const usedThisRun = new Set(current.map(r => r.keyword.toLowerCase().trim()));

const allFiltered = $('FilterKeywords').all().map(i => i.json);
const candidatePool = new Map();

allFiltered.forEach(r => {
  (r.related_keywords || []).forEach(rk => {
    const key = rk.toLowerCase().trim();
    if (!existing.has(key) && !usedThisRun.has(key) && !candidatePool.has(key)) {
      candidatePool.set(key, {
        keyword: rk, volume: null, difficulty: null, intent: null,
        cpc: null, has_paa: false, score: 0, source: 'related_backfill'
      });
    }
  });
});

const topUp = Array.from(candidatePool.values()).slice(0, needed);

return [...current, ...topUp].map(r => ({ json: r }));// Loop over input items and add a new field called 'myNewField' to the

const data = $json.tasks?.[0]?.result?.[0];
const items = data?.items ?? [];

const excludedDomains = ['reddit.com', 'youtube.com'];

const organicResults = items
  .filter(i => i.type === 'organic')
  .filter(i => !excludedDomains.some(d => (i.domain || '').includes(d)))
  .slice(0, 5)
  .map(i => ({
    title: i.title,
    url: i.url,
    domain: i.domain,
    description: i.description
  }));

const paaQuestions = items
  .filter(i => i.type === 'people_also_ask')
  .flatMap(i => i.items || [])
  .map(q => q.title);

return {
  json: {
    keyword: data?.keyword,
    top_organic_results: organicResults,
    paa_questions: paaQuestions
  }
};

const items = $input.all();
const grouped = {};

items.forEach(item => {
  const kw = item.json.keyword;
  if (!grouped[kw]) grouped[kw] = [];
  if (grouped[kw].length < 3) grouped[kw].push(item);
});

return Object.values(grouped).flat();

return $input.all().map(item => ({
  json: {
    keyword: item.json.keyword,
    url: item.json.top_organic_results?.url || item.json.url,
    title: item.json.top_organic_results?.title || null,
    description: item.json.top_organic_results?.description || null,
    body_text: null,
    fetch_failed: true
  }
}));

return $input.all().map(item => {
  const text = item.json.body_text || '';
  return {
    json: {
      ...item.json,
      body_text: text.slice(0, 6000)
    }
  };
});

const items = $input.all();
const grouped = {};

items.forEach(item => {
  const kw = item.json.keyword;
  if (!grouped[kw]) grouped[kw] = [];
  grouped[kw].push(item.json);
});

return Object.entries(grouped).map(([keyword, pages]) => ({
  json: {
    keyword,
    pages
  }
}));

const extracted = $input.all();
const original = $('TrimToTop3').all();

return extracted.map((item, i) => ({
  json: {
    keyword: original[i]?.json?.keyword,
    url: original[i]?.json?.top_organic_results?.url || original[i]?.json?.url,
    title: original[i]?.json?.top_organic_results?.title,
    body_text: item.json.body_text
  }
}));

