return $input.all().map((item, i) => {
  const keywordRow = $('RankAndCap').all()[i]?.json || {};
  const draftText = item.json.output?.[0]?.content?.[0]?.text || '';
  const headings = $('CompetitorBrief').all()[i]?.json?.output?.[0]?.content?.[0]?.text?.recommended_headings?.join('; ') || '';

  return {
    json: {
      ...keywordRow,
      draft_content: draftText,
      recommended_headings: headings
    }
  };
});

