const groups = $input.all();
const domainSet = new Set();

groups.forEach(item => {
  (item.json.pages || []).forEach(p => {
    if (p.url) {
      try {
        const domain = new URL(p.url).hostname.replace(/^www\./, '');
        domainSet.add(domain);
      } catch (e) {}
    }
  });
});

return Array.from(domainSet).map(domain => ({ json: { competitor_domain: domain } }));

const responses = $input.all();
const domains = $('ExtractCompetitorDomains').all();

const rows = [];
responses.forEach((resp, i) => {
  const competitor = domains[i]?.json?.competitor_domain || 'unknown';
  const items = resp.json.tasks?.[0]?.result?.[0]?.items || [];
  items.forEach(d => {
    rows.push({
      json: {
        competitor_domain: competitor,
        referring_domain: d.domain,
        domain_rank: d.rank,
        backlinks: d.backlinks,
        why_fit: `Links to ${competitor}, a site ranking for your target keywords`,
        outreach_angle: 'Guest post pitch or resource link request',
        date_added: new Date().toISOString().slice(0, 10)
      }
    });
  });
});

return rows;
